function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limitResult = validateLimit(message.limit);
  if (!limitResult.valid) return limitResult;

  const beforeResult = validateBefore(message.before);
  if (!beforeResult.valid) return beforeResult;

  const data: ListSessionsMessage = {type: 'list_sessions'};
  if (limitResult.limit !== undefined) {
    data.limit = limitResult.limit;
  }
  if (beforeResult.before !== undefined) {
    data.before = beforeResult.before;
  }

  return {valid: true, data};
}

